<script setup lang="ts">import {computed} from 'vue';import {Result} from '../types/domain';import {number} from '../utils/format';const props=defineProps<{result:Result}>();const d=computed(()=>props.result.statistics.dispersion);const nulls=computed(()=>d.value.status==='testable'?d.value.null_R2:[]);const observed=computed(()=>d.value.R2);const hi=computed(()=>Math.max(.01,observed.value??0,...nulls.value)*1.04);const bins=computed(()=>{const b=Array(20).fill(0);nulls.value.forEach(v=>b[Math.min(19,Math.floor(v/hi.value*20))]++);return b});const peak=computed(()=>Math.max(1,...bins.value));const x=(v:number)=>40+v/hi.value*340;</script><template><section class="permutation-plot dispersion-plot"><h3>离散度零分布（标签置换，重算组质心）</h3><template v-if="d.status==='testable'"><svg viewBox="0 0 420 205" role="img" aria-label="组内离散度R平方置换零分布"><rect v-for="(n,i) in bins" :key="i" :x="40+i*17" :y="153-n/peak*105" width="14" :height="n/peak*105"/><line v-if="observed!=null" :x1="x(observed)" :x2="x(observed)" y1="30" y2="157"/><text v-if="observed!=null" :x="Math.min(320,x(observed))" y="21">观测离散度R²</text><text x="40" y="180">0</text><text x="345" y="180">{{number(hi,3)}}</text></svg><p>p=({{d.extreme}}+1)/({{d.null_count}}+1)={{d.p==null?'无法检验':number(d.p,4)}}；有效置换{{d.null_count}}次<span v-if="d.invalid_permutations">，{{d.invalid_permutations}}次无定义已排除且不计为极端</span>。每次置换都重算各组CLR质心与样本距离。</p></template><p v-else class="dispersion-unavailable"><b>无零分布：</b>{{d.reason}}</p></section></template>
